Here’s a small Flask website that stores uploaded files on the server and gives you a shareable link. Visitors must enter the password you chose to download the file.

Save this as `app.py`:

```python
import json
import os
import secrets
from pathlib import Path

from flask import Flask, abort, render_template_string, request, send_file
from werkzeug.security import check_password_hash, generate_password_hash
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 100 * 1024 * 1024  # 100 MB

STORAGE = Path("uploads")
STORAGE.mkdir(exist_ok=True)

PAGE = """
<!doctype html>
<html lang="en">
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Password-protected file sharing</title>
  <style>
    body { font: 16px system-ui, sans-serif; background: #f4f5f8;
           color: #222; padding: 2rem 1rem; }
    main { max-width: 520px; margin: 3rem auto; background: white;
           padding: 2rem; border-radius: 12px; }
    input, button { box-sizing: border-box; width: 100%; margin: .5rem 0 1rem;
                    padding: .75rem; font: inherit; }
    button { background: #334dd8; color: white; border: 0;
             border-radius: 6px; cursor: pointer; }
    .error { color: #b42318; }
    .link { overflow-wrap: anywhere; }
  </style>
</head>
<body>
<main>
  {% if mode == "upload" %}
    <h1>Share a file</h1>
    <p>Upload a file and choose a password. Maximum size: 100 MB.</p>
    <form method="post" enctype="multipart/form-data">
      <label>File <input type="file" name="file" required></label>
      <label>Password <input type="password" name="password" required></label>
      <button type="submit">Create link</button>
    </form>
  {% elif mode == "created" %}
    <h1>Your link is ready</h1>
    <p>Send this link and the password to your friends:</p>
    <p class="link"><a href="{{ link }}">{{ link }}</a></p>
    <a href="/">Share another file</a>
  {% else %}
    <h1>Download a file</h1>
    <p>Enter the password to download <strong>{{ filename }}</strong>.</p>
    {% if error %}<p class="error">{{ error }}</p>{% endif %}
    <form method="post">
      <label>Password <input type="password" name="password" required></label>
      <button type="submit">Download</button>
    </form>
  {% endif %}
</main>
</body>
</html>
"""


@app.route("/", methods=["GET", "POST"])
def upload():
    if request.method == "GET":
        return render_template_string(PAGE, mode="upload")

    file = request.files.get("file")
    password = request.form.get("password", "")

    if not file or not file.filename or not password:
        return "Please select a file and enter a password.", 400

    file_id = secrets.token_urlsafe(24)
    filename = secure_filename(file.filename) or "download"

    file.save(STORAGE / f"{file_id}.bin")
    metadata = {
        "filename": filename,
        "password_hash": generate_password_hash(password),
    }
    (STORAGE / f"{file_id}.json").write_text(json.dumps(metadata))

    link = request.url_root.rstrip("/") + "/s/" + file_id
    return render_template_string(PAGE, mode="created", link=link)


@app.route("/s/<file_id>", methods=["GET", "POST"])
def download(file_id):
    # IDs contain only URL-safe characters; reject anything else.
    if not file_id or any(c not in
                          "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
                          for c in file_id):
        abort(404)

    metadata_path = STORAGE / f"{file_id}.json"
    file_path = STORAGE / f"{file_id}.bin"

    if not metadata_path.is_file() or not file_path.is_file():
        abort(404)

    metadata = json.loads(metadata_path.read_text())

    if request.method == "POST":
        if check_password_hash(metadata["password_hash"],
                               request.form.get("password", "")):
            return send_file(
                file_path,
                as_attachment=True,
                download_name=metadata["filename"],
            )
        return render_template_string(
            PAGE, mode="download", filename=metadata["filename"],
            error="Incorrect password."
        ), 403

    return render_template_string(
        PAGE, mode="download", filename=metadata["filename"], error=None
    )


@app.errorhandler(413)
def too_large(error):
    return "File is too large. The maximum size is 100 MB.", 413


if __name__ == "__main__":
    app.run(port=int(os.environ.get("PORT", 5000)))
```

Install and run it:

```bash
pip install flask
python app.py
```

Open `http://localhost:5000`. To share links with friends, deploy the app to a publicly accessible server with persistent storage and HTTPS.

**Before public use:** add rate limiting to deter password guessing, upload limits/abuse controls, and a way to delete or expire files. The files are stored on disk without encryption. Send passwords separately from links.

